'use strict';

const fs = require('fs');
const path = require('path');

const DEFAULTS = {
  port: 3000,
  host: '127.0.0.1',
};

const ROOT = __dirname;
const INPUT_PATH = path.join(ROOT, 'config.json');
const OUTPUT_PATH = path.join(ROOT, 'config.out.json');

function isBlank(value) {
  return value === undefined || value === null || value === '';
}

function loadConfig(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      return {};
    }
    throw err;
  }

  if (raw.trim() === '') {
    return {};
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(`config.json is not valid JSON: ${err.message}`);
  }

  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error('config.json must contain a JSON object');
  }

  return parsed;
}

function applyDefaults(config) {
  const result = { ...config };
  const applied = [];

  for (const [key, value] of Object.entries(DEFAULTS)) {
    if (isBlank(result[key])) {
      result[key] = value;
      applied.push(key);
    }
  }

  return { result, applied };
}

function main() {
  const config = loadConfig(INPUT_PATH);
  const { result, applied } = applyDefaults(config);

  fs.writeFileSync(OUTPUT_PATH, `${JSON.stringify(result, null, 2)}\n`, 'utf8');

  console.log(`read:    ${path.relative(ROOT, INPUT_PATH)}`);
  console.log(`wrote:   ${path.relative(ROOT, OUTPUT_PATH)}`);
  console.log(
    applied.length > 0
      ? `applied defaults: ${applied.join(', ')}`
      : 'applied defaults: none'
  );
  console.log(`config:  ${JSON.stringify(result)}`);
}

try {
  main();
} catch (err) {
  console.error(`config-loader failed: ${err.message}`);
  process.exitCode = 1;
}

